new_src='''from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]

    row_separators = {r for r, row in enumerate(grid)
                      if len(set(row)) == 1 and row[0] != background}
    col_separators = {c for c in range(w)
                      if len({grid[r][c] for r in range(h)}) == 1
                      and grid[0][c] != background}

    def spans(size, separators):
        result, start = [], 0
        for i in sorted(separators):
            if start < i:
                result.append((start, i))
            start = i + 1
        if start < size:
            result.append((start, size))
        return result

    rows, cols = spans(h, row_separators), spans(w, col_separators)
    panels = [(r0, r1, c0, c1) for r0, r1 in rows for c0, c1 in cols]
    if len(panels) <= 1:
        return [row[:] for row in grid]

    def signal_count(panel):
        r0, r1, c0, c1 = panel
        return sum(grid[r][c] != background
                   for r in range(r0, r1) for c in range(c0, c1))

    source = max(panels, key=signal_count)
    r0, r1, c0, c1 = source
    ph, pw = r1 - r0, c1 - c0
    output = [row[:] for row in grid]
    for a, b, x, y in panels:
        for r in range(a, b):
            for c in range(x, y):
                output[r][c] = grid[r0 + (r - a) % ph][c0 + (c - x) % pw]
    return output
'''
